'use strict';
// The island's node:http SERVER, probed over a RAW node:net socket.
//
// The server leg lands before the client leg, so the probe here speaks
// HTTP/1.1 by hand rather than through http.request — which also makes
// this the sharper test of the two: the assertion is the WIRE, not a
// parser's reading of it. The status line, the header block and the
// framing all have to be byte-right.
//
// Node is the oracle, so the two headers that cannot agree across runs
// are dropped: Date (a clock) and anything carrying the ephemeral port.
const http = require('http');
const net = require('net');

function app(req, res) {
  if (req.method === 'GET' && req.url === '/text') {
    const body = 'hello from httpsrvzoo';
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.setHeader('Content-Length', Buffer.byteLength(body));
    res.setHeader('X-Custom', 'yes');
    res.end(body);
    return;
  }
  if (req.method === 'POST' && req.url === '/echo') {
    const chunks = [];
    req.on('data', (c) => { chunks.push(c); });
    req.on('end', () => {
      const raw = Buffer.concat(chunks);
      const body = JSON.stringify({ got: JSON.parse(raw.toString('utf8')), n: raw.length });
      res.statusCode = 201;
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('Content-Length', Buffer.byteLength(body));
      res.end(body);
    });
    return;
  }
  // finalhandler's 404: unpipe, then a writeHead whose headers reach the
  // WIRE without entering the readable store — Node's rule, pinned by
  // reporting getHeaderNames() in the body (it must be empty).
  req.unpipe();
  const names = JSON.stringify(res.getHeaderNames());
  const body = 'Cannot ' + req.method + ' ' + req.url + ' names=' + names;
  res.writeHead(404, {
    'Content-Type': 'text/plain; charset=utf-8',
    'Content-Length': String(Buffer.byteLength(body)),
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(body);
}

/** The wire, minus the fields no two runs can agree on. */
function normalize(text) {
  const cut = text.indexOf('\r\n\r\n');
  const head = cut < 0 ? text : text.slice(0, cut);
  const body = cut < 0 ? '' : text.slice(cut + 4);
  const lines = head.split('\r\n').filter((line) => !/^date:/i.test(line));
  return lines.concat(['', JSON.stringify(body)]).join('\n');
}

function probe(port, raw, out, next) {
  const sock = net.createConnection({ port, host: '127.0.0.1' }, () => {
    sock.write(raw);
  });
  let text = '';
  sock.setEncoding('utf8');
  sock.on('data', (c) => { text += c; });
  sock.on('error', (e) => { out.push('probe error ' + e.message); });
  sock.on('close', () => { out.push(normalize(text)); next(); });
}

exports.report = function report(done) {
  const out = [];
  const server = http.createServer(app);
  server.on('error', (e) => { out.push('server error ' + e.message); done(out.join('\n')); });
  server.listen(0, '127.0.0.1', () => {
    const a = server.address();
    out.push('listening family=' + a.family + ' address=' + a.address + ' port>0=' + (a.port > 0));
    const payload = JSON.stringify({ hi: 'there', xs: [1, 2, 3] });
    const requests = [
      'GET /text HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n',
      'POST /echo HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Type: application/json\r\n' +
        'Content-Length: ' + Buffer.byteLength(payload) + '\r\nConnection: close\r\n\r\n' + payload,
      'GET /nope HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n',
    ];
    let i = 0;
    const step = () => {
      if (i === requests.length) {
        server.close(() => { out.push('server closed'); done(out.join('\n')); });
        return;
      }
      out.push('--- probe ' + i);
      probe(a.port, requests[i++], out, step);
    };
    step();
  });
};
